ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ5 提案済み"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "5-1:提案内容を理解いただき、方向性の合意をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "5-2:試作品・実機で打ち合わせを実施し、改良点を確認した。")),
                NOT(INCLUDES(CompletionBasis__c, "5-3:改良点を修正した資料で、再度提案を実施した。"))
            )
        )
    )
)
